41	interface Props {
42	  appTitle$: Observable<string>;
43	  breadcrumbs$: Observable<ChromeBreadcrumb[]>;
44	  navGroupEnabled: boolean;
45	  currentNavgroup$: Observable<NavGroupItemInMap | undefined>;
46	  navigateToApp: ApplicationStart['navigateToApp'];
47	}
48	
49	/**
50	 * prepend current nav group into existing breadcrumbs and return new breadcrumbs, the new breadcrumbs will looks like
51	 * Home > Search > Visusalization
52	 * @param breadcrumbs existing breadcrumbs
53	 * @param currentNavGroup current nav group object
54	 * @param navigateToApp
55	 * @returns new breadcrumbs array
56	 */
57	function prependCurrentNavGroupToBreadcrumbs(
58	  breadcrumbs: ChromeBreadcrumb[],
59	  currentNavGroup: NavGroupItemInMap,
60	  navigateToApp: ApplicationStart['navigateToApp']
61	) {
62	  // breadcrumb order is home > navgroup > application, navgroup will be second one
63	  const navGroupInBreadcrumbs =
64	    breadcrumbs.length > 1 && breadcrumbs[1]?.text === currentNavGroup.title;
65	  if (!navGroupInBreadcrumbs) {
66	    const navGroupBreadcrumb: ChromeBreadcrumb = {
67	      text: currentNavGroup.title,
68	      onClick: () => {
69	        if (currentNavGroup.navLinks && currentNavGroup.navLinks.length) {
70	          navigateToApp(currentNavGroup.navLinks[0].id);
71	        }
72	      },
73	    };
74	    const homeBreadcrumb: ChromeBreadcrumb = {
75	      text: i18n.translate('core.breadcrumbs.homeTitle', { defaultMessage: 'Home' }),
76	      onClick: () => {
77	        navigateToApp('home');
78	      },
79	    };
80	    return [homeBreadcrumb, navGroupBreadcrumb, ...breadcrumbs];
81	  }
82	
83	  return breadcrumbs;
84	}
85	
86	export function HeaderBreadcrumbs({
87	  appTitle$,
88	  breadcrumbs$,
89	  navGroupEnabled,
90	  currentNavgroup$,
91	  navigateToApp,
92	}: Props) {
93	  const appTitle = useObservable(appTitle$, 'OpenSearch Dashboards');
94	  const breadcrumbs = useObservable(breadcrumbs$, []);
95	  let crumbs = breadcrumbs;
96	
97	  if (breadcrumbs.length === 0 && appTitle) {
98	    crumbs = [{ text: appTitle }];
99	  }
100	
101	  const currentNavgroup = useObservable(currentNavgroup$, undefined);
102	  if (navGroupEnabled && currentNavgroup) {
103	    crumbs = prependCurrentNavGroupToBreadcrumbs(crumbs, currentNavgroup, navigateToApp);
104	  }
105	
106	  crumbs = crumbs.map((breadcrumb, i) => ({
107	    ...breadcrumb,
108	    'data-test-subj': classNames(
109	      'breadcrumb',
110	      breadcrumb['data-test-subj'],
111	      i === 0 && 'first',
112	      i === crumbs.length - 1 && 'last'
113	    ),
114	  }));
115	
116	  return <EuiHeaderBreadcrumbs breadcrumbs={crumbs} max={10} data-test-subj="breadcrumbs" />;
117	}
